create table if not exists public.telegram_products(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete set null,title text not null,description text,product_type text not null default 'code',access_type text not null default 'free',price bigint not null default 0,bot_username text,telegram_bot_id bigint,is_published boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.telegram_channels(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete set null,title text not null,access_type text not null default 'free',price bigint not null default 0,telegram_channel_id text,is_published boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.bot_integrations(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete set null,bot_username text,telegram_bot_id bigint,encrypted_token text,is_active boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists telegram_products_market_idx on public.telegram_products(is_published,access_type,created_at desc);
